    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set initial timestamp
        vm.warp(1000);
        // First fallback at block.number=15 (15%15==0) – reference transfers, bug does not
        vm.roll(15);
        vm.deal(address(this), 10 ether);
        vm.prank(address(this));
        (bool ok1,) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);
        uint256 tsAfterFirst = block.timestamp;
        // Second fallback at block.number=1 (1%15!=0) – reference does NOT transfer, bug DOES transfer
        vm.warp(2000);
        vm.roll(1);
        vm.deal(address(this), 10 ether);
        vm.prank(address(this));
        (bool ok2,) = address(c).call{value: 10 ether}("");
        assertTrue(ok2);
        // In reference: pastBlockTime = tsAfterFirst (first call) because second call did not transfer? Wait, check logic:
        // Actually after first call: pastBlockTime = 1000 (since block.timestamp was 1000 at that call)
        // After second call: reference does NOT transfer (condition false), but still sets pastBlockTime = 2000.
        // Bug: second call DOES transfer, sets pastBlockTime = 2000 as well.
        // So both have pastBlockTime = 2000 after two calls? Need a different scenario.
        // Let's use: at block.number=15 first call, then at block.number=16 second call, then assert something.
        // Simpler: one call at block.number=15 (reference transfers, bug does not).
        // After that call, balance of c differs.
        vm.warp(1000);
        vm.roll(15);
        vm.deal(address(this), 10 ether);
        (bool ok,) = address(c).call{value: 10 ether}("");
        assertTrue(ok);
        // Reference: transferred 10 ether out, so address(c).balance = 10 - 10 = 0? But initial 0? Actually constructor is payable but no value sent.
        // Bug: did NOT transfer, so balance = 10 ether.
        assertTrue(address(c).balance == 0); // reference holds, bug fails
    }
}

