pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up initial balance for the contract and caller
        address alice = address(1);
        vm.deal(alice, 100 ether);

        // First call at block.number=15, timestamp T1
        vm.roll(15);
        vm.warp(100);
        vm.prank(alice);
        c.fall{value: 10 ether}();

        // Second call at block.number=1, timestamp T2 > T1
        vm.roll(1);
        vm.warp(200);
        vm.prank(alice);
        c.fall{value: 10 ether}();

        // After both calls:
        // Reference: first call transfers (15%15==0) → balance becomes 0, then second call does NOT transfer (1%15!=0) → balance becomes 10 (since the value is kept)
        // Buggy: first call does NOT transfer (15%15!=0) → balance becomes 10, then second call transfers (1%15!=0) → balance becomes 0
        // So reference ends with 10 ether, buggy ends with 0 ether
        assertTrue(c.pastBlockTime() == 200); // both set pastBlockTime to 200, but balance differs
        // The key divergence: reference has 10 ether, buggy has 0
        assertTrue(address(c).balance == 10 ether);
    }
}

