pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup: fund the test contract with 20 ether to send
        vm.deal(address(this), 20 ether);

        // First call: block.timestamp = 100, block.number = 15 (so transfer happens and balance becomes 10)
        // But for the test we only care about pastBlockTime
        vm.warp(100);
        vm.roll(1);  // any block not %15 to avoid transfer that clears balance
        c.fallback{value: 10 ether}();  // reference updates pastBlockTime=100, buggy also updates pastBlockTime=100

        // Second call: new timestamp, new block
        vm.warp(200);
        vm.roll(2);
        c.fallback{value: 10 ether}();  
        // Reference: require(200 > 100) passes, then pastBlockTime=200
        // Buggy: no require, so pastBlockTime=200 immediately
        // At this point both have pastBlockTime=200, need to check after? Actually difference appears on next call

        // Let's do a third call to expose the difference:
        vm.warp(300);
        vm.roll(3);
        // If we call fallback now, reference's require(300 > 200) passes, buggy always passes
        // Both will set pastBlockTime=300 again
        // Need a scenario where reference reverts and buggy doesn't

        // Simpler: after the second call, in reference pastBlockTime = 200, in buggy also 200.
        // The difference appears only on a call with timestamp == pastBlockTime (same second).
        // Let's make third call with same timestamp as second (block.timestamp == pastBlockTime):
        vm.warp(200);  // same as before
        vm.roll(4);
        vm.startPrank(address(0x1234));
        vm.deal(address(0x1234), 10 ether);
        try c.fallback{value: 10 ether}() {
            // Buggy: no require, so succeeds and updates pastBlockTime=200 (no change)
            // This path executes only on buggy
        } catch {
            revert("test setup unexpected");
        }
        vm.stopPrank();

        // For reference, if we had called with timestamp=200 after pastBlockTime=200, it would revert.
        // But we can't test that revert directly without try/catch on a separate call.
        // So let's restructure: we want assertion that reference pastBlockTime differs from buggy after a specific sequence

        // Clear approach: Make two calls with increasing timestamps, then check pastBlockTime after second call
        // Reference: after first call pastBlockTime=100, after second call require(200>100) passes -> pastBlockTime=200
        // Buggy: after first call pastBlockTime=100, after second call (no require) -> pastBlockTime=200
        // Same! The difference is on a call with timestamp NOT greater than pastBlockTime.

        // So let's do: first call at t=100 (pastBlockTime=100), second call at t=100 (same second).
        // Reference: require(100 > 100) false -> reverts, pastBlockTime stays 100.
        // Buggy: no require -> succeeds, pastBlockTime=100 (same). 
        // But then after that, pastBlockTime is same! The difference is the revert.

        // Test the revert difference:
        // Setup: first call at t=100
        vm.warp(100);
        vm.roll(1);
        c.fallback{value: 10 ether}();  // both: pastBlockTime=100

        // Second call at same timestamp t=100, different block
        vm.roll(2);
        bool ok = false;
        try c.fallback{value: 10 ether}() {
            ok = true;  // only buggy reaches here
        } catch {
            ok = false; // reference reverts
        }

        // The buggy contract returns ok=true, reference returns ok=false
        assertTrue(ok == true);
    }
}

