pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up: deployer has enough ether
        vm.deal(address(this), 20 ether);
        // First call: block.timestamp = 100, block.number = 1 (not multiple of 15)
        vm.warp(100);
        vm.roll(1);
        c.fallback{value: 10 ether}();
        // Second call: same timestamp (100), revert expected in reference
        vm.warp(100); // keep same timestamp
        vm.roll(2); // different block number
        bool success;
        try c.fallback{value: 10 ether}() {
            success = true;
        } catch {
            success = false;
        }
        // Reference reverts (success=false), buggy succeeds (success=true)
        // Therefore reference's pastBlockTime = 100, buggy's pastBlockTime = 100 as well but
        // the buggy contract allows the second call, diverging in behavior.
        // We assert that the first call updated pastBlockTime and the second call's success differs.
        // To detect divergence: the reference reverts, so success is false; buggy does not revert.
        // We assert false to match the reference (pass on reference, fail on bug).
        assertTrue(success == false);
    }
}

