pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up two different blocks with same timestamp
        vm.deal(address(this), 20 ether);
        vm.warp(1000);
        vm.roll(1);
        // First call - succeeds in both versions
        (bool ok1,) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);
        uint pastAfterFirst = c.pastBlockTime();
        // Second call in same block but different timestamp (warp forward 1 second)
        vm.warp(1001);
        (bool ok2,) = address(c).call{value: 10 ether}("");
        // In reference, the second call reverts because pastBlockTime was updated to 1000 and require(1001>1000) passes.
        // Actually both versions pass this. We need same timestamp to trigger the difference.
        // Let's fix: use same timestamp for both calls
        vm.warp(1000);
        vm.roll(2);
        (bool ok3,) = address(c).call{value: 10 ether}("");
        // In reference, require(1000 > 1000) fails -> revert. In buggy, no check -> succeeds.
        // So assert that ok3 is false for reference, true for buggy.
        // Use try/catch to capture revert
        bool didSucceed;
        try c.fallback{value: 10 ether}() { 
            didSucceed = true; 
        } catch { 
            didSucceed = false; 
        }
        // For the reference, didSucceed should be false; for buggy, true. 
        // We'll assert the buggy behavior: didSucceed is true (the second call goes through)
        assertTrue(didSucceed);
    }
}

